<script setup lang="ts">
import{computed,defineAsyncComponent,onMounted,ref}from"vue";import{InfoFilled,Printer,RefreshRight}from"@element-plus/icons-vue";import{fetchMonthlyReport,type MonthlyReport}from"../api/monthlyReport";import{useThemeStore}from"../stores/theme";const Chart=defineAsyncComponent(()=>import("../components/ContentRankingChart.vue")),theme=useThemeStore(),data=ref<MonthlyReport|null>(null),month=ref("2026-09"),client=ref("安卓"),loading=ref(false),error=ref(""),drawer=ref(false),nf=new Intl.NumberFormat("zh-CN");const num=(v:number|null|undefined)=>v==null?"--":nf.format(v),pct=(v:number|null|undefined)=>v==null?"--":`${(v*100).toFixed(2)}%`;async function load(){loading.value=true;error.value="";try{data.value=await fetchMonthlyReport({month:month.value,client:client.value})}catch(e){error.value="运营月报加载失败。";console.error(e)}finally{loading.value=false}}const trendOption=computed(()=>({color:[theme.current.primary,"#8ea0bd"],tooltip:{trigger:"axis"},legend:{data:["设备DAU","新增设备"]},grid:{left:58,right:24,top:40,bottom:28},xAxis:{type:"category",data:data.value?.overview.daily.map(x=>x.date.slice(5))??[]},yAxis:[{type:"value"},{type:"value"}],series:[{name:"设备DAU",type:"line",smooth:true,areaStyle:{opacity:.08},data:data.value?.overview.daily.map(x=>x.device_dau)??[]},{name:"新增设备",type:"line",smooth:true,yAxisIndex:1,data:data.value?.overview.daily.map(x=>x.new_device)??[]}]}));const printReport=()=>window.print();onMounted(load)
</script>
<template><main class="main-content page-stack report-page"><header class="page-intro report-screen-only"><div><h2>运营月报</h2><p>复用各看板最终数据层，形成可打印的月度经营摘要。</p></div><button class="source-button" @click="drawer=true"><el-icon><InfoFilled/></el-icon>数据说明</button></header><section class="filter-bar ranking-filter report-screen-only"><label><span>报告月份</span><el-select v-model="month" @change="load"><el-option v-for="value in data?.available_months" :key="value" :label="value" :value="value"/></el-select></label><label><span>大盘客户端</span><el-select v-model="client" @change="load"><el-option label="安卓" value="安卓"/><el-option label="iOS" value="iOS"/><el-option label="M站" value="M站"/></el-select></label><el-button type="primary" :loading="loading" @click="load"><el-icon><RefreshRight/></el-icon>更新报告</el-button><el-button @click="printReport"><el-icon><Printer/></el-icon>打印 / 导出 PDF</el-button><div class="freshness"><span class="status-dot"></span><div><b>最终数据层</b><small>截至 {{data?.coverage.end??'--'}}</small></div></div></section><el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/><article v-if="data" class="monthly-report-paper"><header class="report-cover"><p>MONTHLY OPERATIONS REPORT</p><h1>{{data.month}} 运营月报</h1><span>数据覆盖：{{data.coverage.start??'--'}} 至 {{data.coverage.end??'--'}} · {{data.client}} · {{data.coverage.days}} 个数据日</span></header><section class="report-section"><h2>一、月度整体表现</h2><p>大盘指标使用所选客户端口径；月末指标取报告月份最后一个有效数据日。</p><div class="report-kpi-grid"><div><span>月末设备DAU</span><strong>{{num(data.overview.latest_device_dau)}}</strong></div><div><span>月内新增设备</span><strong>{{num(data.overview.new_device_total)}}</strong></div><div><span>月末播放率</span><strong>{{pct(data.overview.latest_play_rate)}}</strong></div><div><span>人均播放时长</span><strong>{{data.overview.latest_avg_watch_duration?.toFixed(1)??'--'}} 分钟</strong></div><div><span>人均播放次数</span><strong>{{data.overview.latest_avg_play_count?.toFixed(2)??'--'}}</strong></div></div><Chart v-if="data.overview.daily.length" class="report-trend-chart" :option="trendOption"/></section><section class="report-section"><h2>二、内容侧变化</h2><div class="report-columns"><div><h3>热播内容 Top10</h3><ol><li v-for="x in data.content_top" :key="x.name"><span>{{x.name}}</span><strong>{{num(x.value)}}</strong></li></ol></div><div><h3>剧种播放结构</h3><ol><li v-for="x in data.genres" :key="x.name"><span>{{x.name}}</span><strong>{{pct(x.share)}}</strong></li></ol></div></div></section><section class="report-section"><h2>三、用户主动需求</h2><div class="report-columns"><div><h3>热搜内容 Top10</h3><ol><li v-for="x in data.search_top" :key="x.name"><span>{{x.name}}</span><strong>{{num(x.value)}}</strong></li></ol></div><div><h3>热播与热搜重合</h3><p v-if="data.hot_play_overlap.length">Top10 重合 {{data.hot_play_overlap.length}} 个：{{data.hot_play_overlap.join('、')}}。</p><p v-else>当前报告周期暂无 Top10 重合内容。</p></div></div></section><section class="report-section"><h2>四、运营资源承接</h2><div class="report-operation-grid"><div><h3>首页频道有效播放</h3><p v-for="x in data.operations.channels" :key="x.name">{{x.name}}：{{num(x.value)}}</p></div><div><h3>首页板块点击</h3><p v-for="x in data.operations.sections" :key="x.name">{{x.name}}：{{num(x.value)}}</p></div><div><h3>Banner 点击</h3><p v-for="x in data.operations.banners" :key="x.name">{{x.name}}：{{num(x.value)}}</p></div><div><h3>弹窗有效播放</h3><p v-for="x in data.operations.popups" :key="x.name">{{x.name}}：{{num(x.value)}}</p></div></div></section><section class="report-section"><h2>五、本月重点变化与关注项</h2><ul class="report-facts"><li v-for="fact in data.facts" :key="fact">{{fact}}</li><li v-if="!data.facts.length">本周期暂无达到展示条件的重点事实。</li></ul></section><footer>{{data.meta.note}}</footer></article><el-drawer v-model="drawer" title="运营月报来源与口径" size="480px"><div class="source-drawer"><section v-for="source in data?.meta.sources" :key="source.section"><span>{{source.section}}</span><strong>{{source.source}}</strong></section><p>{{data?.meta.note}}</p></div></el-drawer></main></template>
